actions.script:
generatedStr = ec.l10n.format(ec.user.nowTimestamp, 'dd MMM yyyy HH:mm')
def _org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def _activeShop = null; try { def _sc = ec.service.sync().name("zenith.base.ShopServices.get#ActiveShopScope").call(); _activeShop = _sc?.activeShopId } catch (Exception _e) {}
def ef = ec.entity.find("zenith.erp.pos.PosSessionView").orderBy("-openDate").limit(1000)
if (_org && _org != '_NA_') ef.condition("organizationPartyId", _org)
if (_activeShop) ef.condition("facilityId", _activeShop)
def raw = ef.list()
def num = { v -> ec.l10n.format((v ?: 0) as BigDecimal, '#,##0.00') }
def dt = { v -> v == null ? '' : ec.l10n.format(v, 'dd-MM-yyyy HH:mm') }
// XSL-FO is XML: escape &, <, > in data values (e.g. terminal "Bean&Berg")
def x = { v -> (v ?: '').toString().replace('&','&amp;').replace('<','&lt;').replace('>','&gt;') }
def slMap = [PsClosed:'Closed', PsOpen:'Open']
rows = raw.collect { s ->
    [sid:x(s.sessionId), term:x(s.terminalName), op:x(s.operatorPartyId),
     opened:dt(s.openDate), closed:dt(s.closeDate),
     status:(slMap[s.statusId] ?: x(s.statusId)),
     statusColor:(s.statusId == 'PsOpen' ? '#D97706' : '#059669'),
     opening:num(s.openingCash), sales:num(s.totalSales), ret:num(s.totalReturns),
     trans:(((s.totalTransactions ?: 0) as BigDecimal).toBigInteger().toString()),
     closing:num(s.closingCash), diff:num(s.cashDifference)] }
rowCountStr = raw.size().toString()
